export interface PersonalityProfile {
  id: string;
  code: string;
  nameZh: string;
  nameEn: string;
  archetype: PersonalityArchetype;
  temperament: string;
  costume: string;
  props: string[];
  symbols: string[];
  palette: string[];
  pose: string;
  expression: string;
  keywords: [string, string, string];
  tagline: string;
  visualNotes: string;
  styleDirection: CardStyleDirection;
  imagePrompt: string;
  imagePath: string;
  thumbnailPath: string;
  shareImagePath: string;
  reviewStatus: PersonalityProfileStatus;
  assetType: PersonalityAssetType;
  imageReview: {
    status: PersonalityImageReviewStatus;
    sourceFile?: string;
    manifestId?: string;
    manifestCode?: string;
  };
}

