export const personalityProfiles: PersonalityProfile[] = reviewedPersonalityProfiles;

export function getPersonalityProfileById(id: string) {
  return personalityProfiles.find((item) => item.id === id);
}

export function getReviewedPersonalityProfiles() {
  return reviewedPersonalityProfiles;
}

export function getPreviewProfiles() {
  return reviewedPersonalityProfiles.filter((item) => item.reviewStatus === "reviewed");
}

export function validatePersonalityProfiles() {
  const destinyIds = new Set(destinyTypes.map((item) => item.id));
  const profileIds = new Set(personalityProfiles.map((item) => item.id));
  const duplicateIds = personalityProfiles.map((item) => item.id).filter((id, index, arr) => arr.indexOf(id) !== index);
  const duplicateNameEn = personalityProfiles.map((item) => item.nameEn).filter((name, index, arr) => arr.indexOf(name) !== index);

  return {
    total: personalityProfiles.length,
    reviewed: reviewedPersonalityProfiles.length,
    fallback: 0,
    imageReady: personalityProfiles.filter((item) => item.imageReview.status === "image-ready").length,
    pendingImage: personalityProfiles.filter((item) => item.imageReview.status !== "image-ready").length,
    destinyTypeTotal: destinyTypes.length,
    missingProfileIds: Array.from(destinyIds).filter((id) => !profileIds.has(id)),
    extraProfileIds: Array.from(profileIds).filter((id) => !destinyIds.has(id)),
    duplicateIds: Array.from(new Set(duplicateIds)),
    duplicateNameEn: Array.from(new Set(duplicateNameEn)),
    incompleteProfiles: personalityProfiles
      .filter((item) => !item.id || !item.code || !item.nameZh || !item.nameEn || !item.archetype || !item.temperament || !item.costume || item.props.length < 1 || item.symbols.length < 2 || item.palette.length < 2 || !item.pose || !item.expression || item.keywords.length !== 3 || !item.tagline || !item.visualNotes || !item.imagePrompt || !item.imagePath || !item.thumbnailPath || !item.shareImagePath || !item.assetType || !item.imageReview.status)
      .map((item) => item.id),
    keywordCountErrors: personalityProfiles.filter((item) => item.keywords.length !== 3).map((item) => item.id),
    missingImagePromptIds: personalityProfiles.filter((item) => !item.imagePrompt).map((item) => item.id),
    missingImagePathIds: personalityProfiles.filter((item) => !item.imagePath || !item.thumbnailPath || !item.shareImagePath).map((item) => item.id),
  };
}
